bool canFinish(long long n, std::vector<std::vector<long long> > prerequisites) {
    std::vector<std::vector<long long> > adjacency((std::size_t)n);
    std::vector<long long> indegree((std::size_t)n, 0);
    for (std::size_t i = 0; i < prerequisites.size(); ++i) {
        long long after = prerequisites[i][0], before = prerequisites[i][1];
        adjacency[(std::size_t)before].push_back(after);
        indegree[(std::size_t)after] += 1;
    }
    std::vector<long long> queue;
    for (long long i = 0; i < n; ++i) if (indegree[(std::size_t)i] == 0) queue.push_back(i);
    long long seen = 0;
    while (!queue.empty()) {
        long long node = queue.back();
        queue.pop_back();
        ++seen;
        const std::vector<long long>& next = adjacency[(std::size_t)node];
        for (std::size_t k = 0; k < next.size(); ++k) {
            if (--indegree[(std::size_t)next[k]] == 0) queue.push_back(next[k]);
        }
    }
    return seen == n;
}
